function toMysqlDate(value) {
  const date = value ? new Date(value) : new Date();
  if (Number.isNaN(date.getTime())) return new Date().toISOString().slice(0, 19).replace('T', ' ');
  return date.toISOString().slice(0, 19).replace('T', ' ');
}

function parseJsonField(value, fallback = null) {
  if (value === null || value === undefined || value === '') return fallback;
  if (typeof value === 'object') return value;
  try {
    return JSON.parse(value);
  } catch {
    return fallback;
  }
}

function normalizeTrackedProjectionRow(row) {
  if (!row) return null;
  return {
    id: row.id,
    sourceAnalysisId: row.source_analysis_id || null,
    symbol: row.symbol,
    tradeMode: row.trade_mode,
    decision: row.decision,
    entryPrice: row.entry_price === null || row.entry_price === undefined ? null : Number(row.entry_price),
    stopLoss: row.stop_loss === null || row.stop_loss === undefined ? null : Number(row.stop_loss),
    takeProfit1: row.take_profit_1 === null || row.take_profit_1 === undefined ? null : Number(row.take_profit_1),
    takeProfit2: row.take_profit_2 === null || row.take_profit_2 === undefined ? null : Number(row.take_profit_2),
    takeProfit3: row.take_profit_3 === null || row.take_profit_3 === undefined ? null : Number(row.take_profit_3),
    invalidation: row.invalidation || null,
    invalidationPrice: row.invalidation_price === null || row.invalidation_price === undefined ? null : Number(row.invalidation_price),
    tradeTrigger: row.trade_trigger,
    confidence: Number(row.confidence || 0),
    status: row.status,
    currentPrice: row.current_price === null || row.current_price === undefined ? null : Number(row.current_price),
    lastCheckedAt: row.last_checked_at ? new Date(row.last_checked_at).toISOString() : null,
    triggeredAt: row.triggered_at ? new Date(row.triggered_at).toISOString() : null,
    invalidatedAt: row.invalidated_at ? new Date(row.invalidated_at).toISOString() : null,
    expiresAt: row.expires_at ? new Date(row.expires_at).toISOString() : null,
    createdAt: row.created_at ? new Date(row.created_at).toISOString() : null,
    evaluation: parseJsonField(row.evaluation_json, null),
    originalAnalysis: parseJsonField(row.original_analysis_json, null),
  };
}

function formatAppDateTime(value = new Date()) {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) return null;
  return new Intl.DateTimeFormat('en-BD', {
    timeZone: APP_TIME_ZONE,
    year: 'numeric',
    month: 'short',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: true,
  }).format(date);
}

function getDbPool() {
  if (!hasDbConfig) return null;
  if (!dbPool) {
    dbPool = mysql.createPool({
      host: DB_HOST,
      port: DB_PORT,
      user: DB_USER,
      password: DB_PASSWORD,
      database: DB_NAME,
      waitForConnections: true,
      // Sized against TWO host limits that pull in opposite directions:
      //   wait_timeout = 20              → the server hangs up on any connection idle for 20s
      //   max_connections_per_hour = 500 → but only 500 NEW connections may be opened per hour
      // So the pool must neither hold dead sockets (hangs) nor churn through fresh ones
      // (lockout: "has exceeded the max_connections_per_hour resource", which fails every
      // write and resolver until the hour rolls over). The answer is a modest pool of
      // long-lived connections kept warm by keepAlivePing below — replaced rarely, never
      // recycled on a timer. 10 covers the scanners plus a UI read without racing the cap.
      connectionLimit: Number(process.env.DB_POOL_SIZE || 10),
      ssl: DB_SSL ? { rejectUnauthorized: false } : undefined,
      timezone: 'Z',
      // The shared host runs wait_timeout=interactive_timeout=20s, so it hangs up on any
      // connection idle for 20 seconds. mysql2's default idleTimeout is 60s, so the pool
      // used to keep sockets the server had already closed, hand one out, write a query
      // into it, and never receive a reply — the promise never settles, the connection is
      // never returned, and after 5 of those the whole pool is wedged. Symptom: every
      // DB-backed endpoint hangs forever while in-memory ones stay fast, candle/signal
      // writes stop, and pending requests pile up until the heap OOMs (~15-20 min).
      // Idle sockets are NOT recycled on a timer. Doing that (idleTimeout 10s) cured the
      // hangs but opened a fresh connection every 10s per slot, which tripped the 500/hour
      // cap within minutes. keepAlivePing keeps them under wait_timeout instead, so a
      // connection stays the same connection for hours.
      idleTimeout: 600000,
      maxIdle: Number(process.env.DB_POOL_SIZE || 10),
      enableKeepAlive: true,
      keepAliveInitialDelay: 5000,
      connectTimeout: 15000,
    });
    startDbKeepAlive();
  }
  return dbPool;
}

// Touch the pool every 12s — comfortably inside the host's wait_timeout=20 — so idle
// connections stay logged in rather than being hung up on and re-opened. One trivial query
// per interval (300/hour) is far cheaper than the reconnect storm it prevents, and it is what
// makes long-lived connections viable against max_connections_per_hour=500.
let dbKeepAliveTimer = null;
function startDbKeepAlive() {
  if (dbKeepAliveTimer) return;
  dbKeepAliveTimer = setInterval(() => {
    if (!dbPool) return;
    dbPool.query('SELECT 1').catch(() => { /* a failed ping must never surface as an app error */ });
  }, 12000);
  if (typeof dbKeepAliveTimer.unref === 'function') dbKeepAliveTimer.unref();
}

async function addColumnIfMissing(pool, table, column, definition) {
  const [rows] = await pool.query(`SHOW COLUMNS FROM ${table} LIKE ?`, [column]);
  if (rows.length) return;
  await pool.query(`ALTER TABLE ${table} ADD COLUMN ${column} ${definition}`);
}

async function addIndexIfMissing(pool, table, indexName, columns) {
  const [rows] = await pool.query(`SHOW INDEX FROM ${table} WHERE Key_name = ?`, [indexName]);
  if (rows.length) return;
  await pool.query(`ALTER TABLE ${table} ADD INDEX ${indexName} ${columns}`);
}

async function ensureTrackedAiProjectionSchema(pool) {
  await addColumnIfMissing(pool, 'mt5_tracked_ai_projections', 'source_analysis_id', 'VARCHAR(128) NULL');
  await addColumnIfMissing(pool, 'mt5_tracked_ai_projections', 'take_profit_3', 'DECIMAL(20,8) NULL');
  await addColumnIfMissing(pool, 'mt5_tracked_ai_projections', 'invalidation_price', 'DECIMAL(20,8) NULL');
  await addColumnIfMissing(pool, 'mt5_tracked_ai_projections', 'current_price', 'DECIMAL(20,8) NULL');
  await addColumnIfMissing(pool, 'mt5_tracked_ai_projections', 'last_checked_at', 'DATETIME(3) NULL');
  await addColumnIfMissing(pool, 'mt5_tracked_ai_projections', 'triggered_at', 'DATETIME(3) NULL');
  await addColumnIfMissing(pool, 'mt5_tracked_ai_projections', 'invalidated_at', 'DATETIME(3) NULL');
  await addColumnIfMissing(pool, 'mt5_tracked_ai_projections', 'evaluation_json', 'LONGTEXT NULL');
  await addColumnIfMissing(pool, 'mt5_tracked_ai_projections', 'original_analysis_json', 'LONGTEXT NULL');
  // HOLD watch-mode tracking may not have a projected entry price.
  await pool.query('ALTER TABLE mt5_tracked_ai_projections MODIFY COLUMN entry_price DECIMAL(20,8) NULL');
}

