  fixedTime: true,
  postNewsForex: false,
  postNewsFixed: true,
  highImpactNews: true,
  aiTracked: false,
  forecast: true,
  signalTracker: true,
  // Breakout alerts: master email toggle + min grade (B | A | A+). Browser desktop
